    private static func data(_ parts: [String]) -> Data? {
        Data(base64Encoded: parts.joined())
    }

    /// Writes embedded media to a temp file and returns its URL.
    static func url(_ parts: [String], filename: String) -> URL? {
        guard let d = data(parts) else { return nil }
        let dir = FileManager.default.temporaryDirectory.appendingPathComponent("matino_media", isDirectory: true)
        try? FileManager.default.createDirectory(at: dir, withIntermediateDirectories: true)
        let url = dir.appendingPathComponent(filename)
        // Rewrite when the embedded bytes change (e.g. after an app update),
        // otherwise an old cached file from a previous build would be used.
        if let cached = try? Data(contentsOf: url), cached == d { return url }
        try? d.write(to: url, options: .atomic)
        return url
    }

    /// Returns embedded media as Data (for images).
    static func imageData(_ parts: [String]) -> Data? {
        data(parts)
    }
}
